129	const CatalogPrinter* OrcaPrinterBackend::model_of(const std::string& printer_name) const
130	{
131	    const PresetBundle* presets = wxGetApp().preset_bundle;
132	    if (presets == nullptr)
133	        return nullptr;
134	    const Preset* preset = presets->printers.find_preset(printer_name, false);
135	    if (preset == nullptr)
136	        return nullptr;
137	    const std::string model = preset->config.opt_string("printer_model");
138	    const auto        found = std::find_if(m_models.begin(), m_models.end(),
139	                                           [&model](const CatalogPrinter& printer) { return printer.model_id == model; });
140	    return found == m_models.end() ? nullptr : &*found;
141	}
