297	std::string OrcaPrinterBackend::add_printer(const AddPrinterRequest& request, SavedPrinter& added)
298	{
299	    // Installing and selecting the printer preset marks the open project
300	    // dirty the same way any preset switch does (Tab::select_preset ->
301	    // on_presets_changed -> update_project_dirty_from_presets), even though
302	    // nothing about the project itself changed. Only re-baseline a project
303	    // that was clean before this call, the same way Plater's own new-project
304	    // and load-project paths already do -- a real pending edit must stay
305	    // visible. And only a project with nothing saved to disk yet: for one
306	    // loaded from a file, this switch is now that project's own printer,
307	    // and re-baselining it would mean closing the project never prompts to
308	    // save that -- a real edit, made to look like nothing happened. F9 on
309	    // printer-panel-review-fixes-handoff.md.
310	    const bool was_clean       = !m_plater.is_project_dirty();
311	    const bool no_project_file = m_plater.get_project_filename().IsEmpty();
312	
313	    std::string error;
314	    if (!SetupCommands::install_and_select_printer(m_plater, request.vendor_id, request.model_id, request.variant,
315	                                                  request.material, error))
316	        return error.empty() ? std::string("This printer could not be installed.") : error;
317	
318	    if (was_clean && no_project_file) {
319	        m_plater.reset_project_dirty_initial_presets();
320	        m_plater.update_project_dirty_from_presets();
321	    }
322	
323	    const std::string name =
324	        Printers::add_named_printer(m_plater, request.name.empty() ? request.model_id : request.name, request.device_id);
325	    // With the new printer selected, the plate goes through the sidebar's
326	    // own selection, which records it as this printer's plate
327	    // (app_config printer_settings), as a pick in the sidebar would.
328	    if (request.plate && !SetupCommands::select_bed_type(m_plater, *request.plate))
329	        throw std::logic_error("The printer form offered a plate OrcaSlicer does not offer for " + name);
330	
331	    for (const SavedPrinter& saved : saved_printers())
332	        if (saved.name == name)
333	            added = saved;
334	    return {};
335	}
336	
337	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
338	                                               std::vector<std::string>& discarded)
339	{
340	    std::vector<SavedPrinter> printers = saved_printers();
341	    const auto                found    = std::find_if(printers.begin(), printers.end(),
342	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
343	    if (found == printers.end())
344	        return "This app no longer has a printer called \"" + request.name + "\".";
345	
346	    if (request.nozzle) {
347	        const PrinterCandidate* variant = nullptr;
348	        for (const PrinterCandidate& candidate : m_catalog.candidates())
349	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
350	                variant = &candidate;
351	        if (variant == nullptr)
352	            return found->model.empty() ? std::string("The app has no preset of this printer with that nozzle size.") :
353	                                          "The app has no " + found->model + " preset with that nozzle size.";
354	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name, discarded);
355	        if (!problem.empty())
356	            return problem.ToStdString();
357	    }
358	
359	    for (const SavedPrinter& saved : saved_printers())
360	        if (saved.name == request.name)
361	            changed = saved;
362	    return {};
363	}
364	
365	std::string OrcaPrinterBackend::remove_printer(const std::string& name)
366	{
367	    return std::string(Printers::remove_named_printer(m_plater, name).ToUTF8());
368	}
369	
370	ManualPrinterResult OrcaPrinterBackend::run_manual_setup()
371	{
372	    // OrcaSlicer's own printer wizard, unchanged, and the printers it
373	    // installs are saved under their own names the way the old dialog's
374	    // manual path did.
375	    const Printers::VendorMap before = wxGetApp().app_config->vendors();
376	    // False when the person closed the wizard without applying it.
377	    if (!wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS))
378	        return {};
379	    const auto names = Printers::name_installed_printers(m_plater, before);
380	    ManualPrinterResult result;
381	    result.applied = true;
382	    for (const SavedPrinter& saved : saved_printers())
383	        if (std::find(names.begin(), names.end(), saved.name) != names.end())
384	            result.added.push_back(saved);
385	    return result;
386	}
