388	void OrcaPrinterBackend::prepare_connection(const std::string& name)
389	{
390	    const CatalogPrinter* model = model_of(name);
391	    if (model == nullptr || model->vendor_id != "BBL")
392	        return;
393	    NetworkAgent* agent = wxGetApp().getAgent();
394	    const std::string fake = fake_bambu_printer_agent_id(wxGetApp().app_config);
395	    if (agent == nullptr || (fake.empty() && !NetworkAgent::is_network_module_loaded()))
396	        return;
397	    const std::string wanted = fake.empty() ? BBL_PRINTER_AGENT_ID : fake;
398	    if (!agent->get_printer_agent() || agent->get_printer_agent()->get_agent_info().id != wanted) {
399	        // A connection gesture selects the networking provider, not a slicing
400	        // preset. NetworkAgent owns callback transfer and disconnects the old
401	        // provider; the open project's settings and unsaved edits stay intact.
402	        // Orca's profile-driven policy takes the provider back the next time
403	        // the printer profile changes; connecting again reinstalls it.
404	        auto provider = NetworkAgentFactory::create_printer_agent_by_id(
405	            wanted, agent->get_cloud_agent(BBL_CLOUD_PROVIDER), Slic3r::data_dir());
406	        if (!provider)
407	            throw std::runtime_error("The registered Bambu printer agent could not be created");
408	        agent->set_printer_agent(std::move(provider));
409	        wxGetApp().sidebar().update_all_preset_comboboxes();
410	    }
411	    agent->start_discovery(true, false);
412	}
413	
414	DiscoveryPort OrcaPrinterBackend::discovery_port()
415	{
416	    // The fake printer has no socket; on Windows this is not implemented, and
417	    // whether a held port hides printers there has not been tested. "Ours" makes
418	    // no claim: the search reports as if nothing were in the way.
419	#ifdef _WIN32
420	    return DiscoveryPort::Ours;
421	#else
422	    if (!fake_bambu_printer_agent_id(wxGetApp().app_config).empty())
423	        return DiscoveryPort::Ours;
424	    constexpr int port = 2021;
425	    // The plug-in's socket lives in this process and has no API to ask about.
426	    for (int fd = 0; fd < std::min(getdtablesize(), 4096); ++fd) {
427	        sockaddr_in address{};
428	        socklen_t   size = sizeof(address);
429	        int         type = 0;
430	        socklen_t   type_size = sizeof(type);
431	        if (getsockname(fd, reinterpret_cast<sockaddr*>(&address), &size) == 0 && address.sin_family == AF_INET &&
432	            ntohs(address.sin_port) == port && getsockopt(fd, SOL_SOCKET, SO_TYPE, &type, &type_size) == 0 && type == SOCK_DGRAM)
433	            return DiscoveryPort::Ours;
434	    }
435	    const int probe = ::socket(AF_INET, SOCK_DGRAM, 0);
436	    if (probe < 0)
437	        return DiscoveryPort::Ours;
438	    sockaddr_in address{};
439	    address.sin_family      = AF_INET;
440	    address.sin_addr.s_addr = htonl(INADDR_ANY);
441	    address.sin_port        = htons(port);
442	    const bool bound        = ::bind(probe, reinterpret_cast<sockaddr*>(&address), sizeof(address)) == 0;
443	    const int  why          = errno;
444	    ::close(probe);
445	    return bound ? DiscoveryPort::Free : why == EADDRINUSE ? DiscoveryPort::Taken : DiscoveryPort::Ours;
446	#endif
447	}
